package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.io.*;
final class SearchWriteContracts {
 static void yes(boolean b,String m)throws Exception{if(!b)throw new Exception(m);}
 static void start(Activity a){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(40,160,40,40);EditText search=new EditText(a);search.setHint("搜索商品");search.setText("原有查询");box.addView(search);EditText filename=new EditText(a);filename.setHint("文档名称");filename.setText("原有文件名");box.addView(filename);a.setContentView(box);new Handler().postDelayed(()->run(a),800);}
 static void run(Activity a){ControlService s=ControlService.instance;JSONObject out=new JSONObject();String oldTask=s==null?"":s.task,oldAllowed=s==null?"":s.allowed;TaskRequest oldRequest=s==null?null:s.activeRequest;int passed=0;try{yes(s!=null&&s.connected&&!s.busy(),"Runtime not idle");AccessibilityNodeInfo root=s.getRootInActiveWindow();yes(root!=null&&a.getPackageName().contentEquals(root.getPackageName()),"Owned fixture lost foreground");passed++;AccessibilityNodeInfo field=root.findAccessibilityNodeInfosByText("原有查询").get(0);s.task="搜索StepX Neo 16+256G手机";s.allowed="com.taobao.taobao";s.activeRequest=new TaskRequest(s.allowed,"去淘宝搜索StepX Neo 16+256G手机，确认型号后停止","StepX Neo 16+256G",false);
 boolean rejected=false;try{s.setPublicText(field,"StepX Neo 16+512G 手机");}catch(ControlService.LocalBoundaryException denied){rejected=true;}yes(rejected,"Wrong variant was written before validation");passed++;field.refresh();yes("原有查询".contentEquals(field.getText()),"Rejected input changed search field");passed++;
 String valid="StepX Neo 16+256G 手机 价格";yes(s.setPublicText(field,valid),"Valid query was not written");passed++;field.refresh();yes(valid.contentEquals(field.getText()),"Valid query native readback mismatch");passed++;
 rejected=false;try{s.setPublicText(field,"其他商品");}catch(ControlService.LocalBoundaryException denied){rejected=true;}yes(rejected,"Unrelated query was written");passed++;field.refresh();yes(valid.contentEquals(field.getText()),"Rejected replacement changed native query");passed++;
 AccessibilityNodeInfo filename=root.findAccessibilityNodeInfosByText("原有文件名").get(0);yes(s.setPublicText(filename,"测试租赁合同"),"Filename incorrectly restricted as search");passed++;filename.refresh();yes("测试租赁合同".contentEquals(filename.getText()),"Filename write missing");passed++;out.put("success",true);
 }catch(Exception e){try{out.put("success",false).put("failure",e.getMessage());}catch(Exception ignored){}}finally{if(s!=null){s.task=oldTask;s.allowed=oldAllowed;s.activeRequest=oldRequest;}try(FileOutputStream f=a.openFileOutput("search-write-contracts.json",0)){f.write(out.put("passed",passed).put("real_network_calls",0).put("third_party_actions",0).toString(2).getBytes("UTF-8"));}catch(Exception ignored){}a.finish();}}
}
